const metaById = new Map();
{
  name: 'my-plugin',
  transform(code, id) {
    metaById.set(id, { /* ... */ });
    return null;
  },
  generateBundle() {
    for (const [id, meta] of metaById) { /* use meta */ }
  }
}
```

